<?php require_once("throws/ErzaException.php");class Erza extends PDO{private const AUTHOR_NAME="Filip Matiaska";private const AUTHOR_EMAIL="filmat@post.cz";private const ALPHABET="abcdefghijklmnopqrstuvwxyz";private const RANDOM_ORG_URL="https://www.random.org/integers/?num=1&col=1&base=10&format=plain&rnd=new&min=";public static function RAND_BOOL(){return mt_rand(0,1)==1?true:false;}private static function RAND_CHAR($isSpec){$letters=self::RAND_BOOL()?strtoupper(self::ALPHABET):self::ALPHABET;if($isSpec)$letters.="~!@#$%^&*+/=";return $letters[mt_rand(0,strlen($letters)-1)];}public static function RAND_STRING($length,$isNum,$isSpec,$ip){if($length<=0)throw new ErzaException("Parametr `length` metody 'RAND_STRING' musí obsahovat hodnotu 1 (jedna) nebo vyšší!",$ip);$string="";for($i=0;$i<$length;$i++){if($isNum&&self::RAND_BOOL()&&self::RAND_BOOL()){$string.=mt_rand(0,9);}else{$string.=self::RAND_CHAR($isSpec);}}return $string;}public static function SUPER_RAND($min,$max,$ip){if($min>=$max)throw new ErzaException("Parametr `min` metody 'SUPER_RAND' musí být menší než parametr `max`!",$ip);$vysledek=(int)file_get_contents(self::RANDOM_ORG_URL.$min."&max=".$max);return $vysledek;}private $enterKey,$saltPas,$ip;public function __construct($db_server,$db_name,$db_user,$db_pass,$enterKey,$ip){parent::__construct("mysql:host=".$db_server.";dbname=".$db_name.";charset=utf8",$db_user,$db_pass);parent::setAttribute(parent::ATTR_ERRMODE,parent::ERRMODE_EXCEPTION);$this->ip=$ip;$this->enterKey=md5("KAEDE_Salt*2024_".$enterKey);$this->saltPass=self::RAND_STRING(7,true,true,$ip)."_";}public function getSaltPass($enterKey){if(strcmp(md5("KAEDE_Salt*2024_".$enterKey),$this->enterKey)!=0)throw new ErzaException("WRONG INSTANCE PASSPHRASE FOR CLASS 'Kaede'!",$this->ip);return $this->saltPass;}public function setSaltPass($saltPass,$enterKey){if(strcmp(md5("KAEDE_Salt*2024_".$enterKey),$this->enterKey)!=0)throw new ErzaException("WRONG INSTANCE PASSPHRASE FOR CLASS 'Kaede'!",$this->ip);if(!str_ends_with($saltPass,"_"))$saltPass.="_";$this->saltPass=$saltPass;}public function getIP($enterKey){if(strcmp(md5("KAEDE_Salt*2024_".$enterKey),$this->enterKey)!=0)throw new ErzaException("WRONG INSTANCE PASSPHRASE FOR CLASS 'Kaede'!",$this->ip);return $this->ip;}public function censore_pass($pass,$enterKey){if(strcmp(md5("KAEDE_Salt*2024_".$enterKey),$this->enterKey)!=0)throw new ErzaException("WRONG INSTANCE PASSPHRASE FOR CLASS 'Kaede'!",$this->ip);$censore="";for($i=0;$i<strlen($pass)-2;$i++){$censore.="*";}$censore.=$pass[strlen($pass)-2].$pass[strlen($pass)-1];return $censore;}public function check_username($name,$enterKey){if(strcmp(md5("KAEDE_Salt*2024_".$enterKey),$this->enterKey)!=0)throw new ErzaException("WRONG INSTANCE PASSPHRASE FOR CLASS 'Kaede'!",$this->ip);$result=true;if(strlen($name)<5||strlen($name)>16||!ctype_alnum($name))$result=false;return $result;}public function check_email($email,$enterKey){if(strcmp(md5("KAEDE_Salt*2024_".$enterKey),$this->enterKey)!=0)throw new ErzaException("WRONG INSTANCE PASSPHRASE FOR CLASS 'Kaede'!",$this->ip);$result=true;if(strlen($email)<6||strlen($email)>48||!filter_var($email,FILTER_VALIDATE_EMAIL))$result=false;return $result;}}